package com.hostelhub.controller;
import com.hostelhub.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final StudentRepository s;private final RoomRepository r;private final ComplaintRepository c;private final VisitorRepository v;private final LeaveRequestRepository l; private final MovementRepository m;public DashboardController(StudentRepository s,RoomRepository r,ComplaintRepository c,VisitorRepository v,LeaveRequestRepository l,MovementRepository m){this.s=s;this.r=r;this.c=c;this.v=v;this.l=l;this.m=m;}@GetMapping public Map<String,Object> stats(){long capacity=r.findAll().stream().mapToLong(x->x.getCapacity()).sum();long occupied=r.findAll().stream().mapToLong(x->x.getOccupied()).sum();return Map.ofEntries(Map.entry("students",s.count()),Map.entry("rooms",r.count()),Map.entry("allocated",s.countByRoomIdIsNotNull()),Map.entry("pendingFees",s.countByFeeStatus("PENDING")),Map.entry("openComplaints",c.countByStatus("OPEN")),Map.entry("visitorsInside",v.countByStatus("CHECKED_IN")),Map.entry("pendingLeaves",l.countByStatus("PENDING")),Map.entry("pendingExitRequests",m.countByStatus("REQUESTED")),Map.entry("studentsOut",m.countByStatus("OUT")),Map.entry("capacity",capacity),Map.entry("occupied",occupied),Map.entry("occupancyPercent",capacity==0?0:Math.round(occupied*100.0/capacity)));}}
